const TEMPLATE = 'The system shall produce a «name» report showing «content» for «audience», «frequency».';
function fill(template, values) {
  var thieu = false;
  var out = template.replace(/«([^»]+)»/g, function (_, k) {
    var v = Object.prototype.hasOwnProperty.call(values, k) ? String(values[k]).trim() : '';
    if (!v) thieu = true;
    return v;
  });
  return thieu ? null : out;
}
const REPORT = fill(TEMPLATE, { name: 'Monthly No-show', content: 'the number and rate of no-shows per doctor and per service', audience: 'the clinic manager', frequency: 'on the first day of each month' });
